    private void txtLoginActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_txtLoginActionPerformed
        // capturamos lo que el usuario escribe
    String correo = txtCorreo.getText();
    String password = new String(txtContrasena.getPassword()); 

    if (correo.isEmpty() || password.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Debe ingresar correo y contraseña.", "Campos Vacíos", javax.swing.JOptionPane.WARNING_MESSAGE);
        return; 
    }

    ControladorUsuario controlUsuario = new ControladorUsuario();
    
     /*Este metodo validarlogin, lo creamos en el controlador usuario , de forma parecida al consultar uno para hacer el login con el correo
     y la contraseña tomando como ejemplo el login de la universidad  , y no hacerlo con id y contraseña */
    Usuario usuarioLogueado = controlUsuario.validarLogin(correo, password);

    // login
    if (usuarioLogueado != null) { 
        int rol = usuarioLogueado.getRoll(); 
        
        javax.swing.JOptionPane.showMessageDialog(this, "Bienvenido " + usuarioLogueado.getNombre() + ".", "Acceso Concedido", javax.swing.JOptionPane.INFORMATION_MESSAGE);
         
        // esta parte cconecta el login con el menu principal ---
         FrmMenuPrincipal menu = new FrmMenuPrincipal(rol);
         menu.setVisible(true);
         this.dispose(); 
        //----
    } else {
        javax.swing.JOptionPane.showMessageDialog(this, "Correo o contraseña incorrectos.", "Error de Acceso", javax.swing.JOptionPane.ERROR_MESSAGE);
        txtContrasena.setText(""); 
    }
        
    }//GEN-LAST:event_txtLoginActionPerformed

